}"},{"rank":2,"score":42.6997,"file_path":"internal/ui/oci_resources/commands.go","start_line":523,"end_line":557,"focus_line":523,"snippet_start_line":523,"snippet_end_line":557,"symbol_start_line":523,"symbol_end_line":557,"language":"Go","kind":"function","symbol_id":"local/nexus-recorded-fixtures-devdesk-511:Go:internal/ui/oci_resources/commands.go:function:detectRegistryGroupCmd","symbol_name":"detectRegistryGroupCmd","qualified_name":"detectRegistryGroupCmd","signature":"func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), groupDetectTimeout)
		defer cancel()

		username := reg.Username
		// D12: a registry the user marked anonymous is probed anonymously.
		// Docker keys credentials by host, so without this gate the credentials
		// stored for any registry on that host went out to all of them — which,
		// for a Nexus instance, is every repository it serves.
		if config.UsesCredentials(config.ResolveAuthMode(reg, nil)) {
			username, password = discoveryCreds(reg, username, password)
		} else {
			username, password = "", ""
