	// Resolve which URL to use for the Nexus API call.
	apiBase := info.ManagementURL
	if apiBase == "" {
		apiBase = info.URL
	}

	host, repoName, err := parseNexusURL(apiBase)
	if err != nil {
		// Not an error: a URL that is not a Nexus repository path is a settled
		// answer, not a failure to reach one.
		// The cause only: a URL that does not parse may hold a password, and
		// url.Error repeats it whole.
		var ue *url.Error
		if errors.As(err, &ue) {
			err = ue.Err
		}
		log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
		return nil, nil
	}

	hasAuth := info.Username != "" && info.Password != ""
	log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)

	// Step 1: generic endpoint — confirms this repo is a group, gets its format,
	// and may already include memberNames in the attributes field (no admin privilege needed).
	repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
	if err != nil {
		return nil, err
	}
	if repoType != "group" {
		return nil, nil
	}

	if len(members) > 0 {
		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
		return members, nil
	}

	// Step 2: format-specific endpoint — requires nx-repository-admin privilege
	// but returns memberNames reliably on Nexus instances that support it.
	members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
	if err != nil {
		return nil, err
	}
	log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
	return members, nil
}"},{"rank":4,"score":40.5018,"file_path":"internal/registrymgr/detector.go","start_line":57,"end_line":61,"focus_line":57,"snippet_start_line":57,"snippet_end_line":61,"symbol_start_line":48,"symbol_end_line":58,"language":"Go","kind":"type","symbol_id":"local/nexus-recorded-fixtures-devdesk-511:Go:internal/registrymgr/detector.go:type:Detector","symbol_name":"Detector","qualified_name":"Detector","signature":"Detector interface { // Provider returns the declared provider this detector serves. Provider() string // DetectGroup returns the group members when the registry is a group repo. // Returns nil, nil when the registry is not a group (not an error), and a // non-nil empty list for a group listed with no member: an empty list is a // settled answer, never a refusal. A manager that refuses to list the members // gives an error satisfying errors.Is(err, ErrMembersRefused); any other // error is a failed discovery. Callers cache a settled answer and no error. DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) }","signals":["path","body","signature","symbol-usage"],"snippet":"	DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error)
