40	func loadCatalogFixtures(t *testing.T) []nexusfixture.Fixture {
41		t.Helper()
42		fixtures, err := nexusfixture.Load("catalog")
43		if err != nil {
44			t.Fatalf("Load(catalog): %v", err)
45		}
46		if len(fixtures) == 0 {
