52	// answeringFixture is the fixture that answers DevDesk's "GET .../v2/_catalog?n=1000"
53	// for a scenario and an identity. Only the group connector's admin answer was
54	// recorded with n=1000 itself; every other one is a no-n recording that the
55	// fake lets answer n=1000 (the tolerance of fakenexus, measured on that one
56	// connector, inferred for hosted and proxy).
57	func answeringFixture(scenario string, id nexusfixture.Identity) string {
58		if scenario == "catalog-group-connector-30482" && id == nexusfixture.Admin {
59			return "page-group-n1000--admin"
60		}
61		return scenario + "--" + string(id)
