64	// totalHits counts every request answered by any fixture of the campaign.
65	func totalHits(s *fakenexus.Server, fixtures []nexusfixture.Fixture) int {
66		n := 0
67		for _, f := range fixtures {
68			n += s.Hits(f.Name)
